// src/api.ts
import axios from "axios";

const api = axios.create({
  baseURL: "http://localhost:5000/api",
});

// Automatically attach correct token based on active route
api.interceptors.request.use(
  (config) => {
    const path = window.location.pathname;

    // BUSINESS ROUTES TAKE PRIORITY WHEN INSIDE /business/*
    const isBusinessRoute = path.startsWith("/business");

    let token: string | null = null;

    const businessToken = localStorage.getItem("businessToken");
    const customerToken = localStorage.getItem("customerToken");

    if (isBusinessRoute) {
      // Business mode → business token first
      token = businessToken || customerToken || null;
    } else {
      // Customer mode → customer token first
      token = customerToken || businessToken || null;
    }

    if (token) {
      config.headers = config.headers || {};
      config.headers.Authorization = `Bearer ${token}`;
    }

    return config;
  },
  (error) => Promise.reject(error)
);

export default api;
